using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent for searching the web and taking notes.
/// </summary>
public sealed class ResearchTools
{
    private static readonly HttpClient HttpClient = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    private readonly List<NoteEntry> _notes = [];

    public IReadOnlyList<NoteEntry> Notes => _notes;

    [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        // Uses the DuckDuckGo Lite HTML endpoint (no API key required).
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite?q={encoded}";

        try
        {
            var html = await HttpClient.GetStringAsync(url);
            var results = ParseDuckDuckGoLite(html);

            if (results.Count == 0)
                return "No results found.";

            var sb = new StringBuilder();
            foreach (var r in results.Take(5))
            {
                sb.AppendLine($"Title: {r.Title}");
                sb.AppendLine($"URL: {r.Url}");
                sb.AppendLine($"Snippet: {r.Snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch the text content of a web page given its URL. Returns the first ~3000 characters of visible text.")]
    public async Task<string> FetchPage(
        [Description("The full URL of the page to fetch")] string url)
    {
        try
        {
            var html = await HttpClient.GetStringAsync(url);
            var text = StripHtmlTags(html);
            return text.Length > 3000 ? text[..3000] + "\n...(truncated)" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    [Description("Save a research note with a topic label and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("A short label for the note topic")] string topic,
        [Description("The note content to save")] string content)
    {
        _notes.Add(new NoteEntry(topic, content, DateTime.UtcNow));
        return $"Note saved under topic '{topic}'. Total notes: {_notes.Count}.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"[{i + 1}] Topic: {note.Topic} ({note.Timestamp:u})");
            sb.AppendLine($"    {note.Content}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private static List<SearchResult> ParseDuckDuckGoLite(string html)
    {
        var results = new List<SearchResult>();

        // DuckDuckGo Lite returns results as table rows with links and snippets.
        var linkMarker = "<a rel=\"nofollow\" href=\"";
        var idx = 0;

        while (idx < html.Length && results.Count < 10)
        {
            idx = html.IndexOf(linkMarker, idx, StringComparison.Ordinal);
            if (idx < 0) break;

            idx += linkMarker.Length;
            var endQuote = html.IndexOf('"', idx);
            if (endQuote < 0) break;

            var rawUrl = html[idx..endQuote];
            if (!rawUrl.StartsWith("http")) { idx = endQuote; continue; }

            // Extract the link text as the title.
            var closeTag = html.IndexOf('>', endQuote);
            var endA = html.IndexOf("</a>", closeTag, StringComparison.OrdinalIgnoreCase);
            var title = (closeTag >= 0 && endA > closeTag)
                ? StripHtmlTags(html[(closeTag + 1)..endA]).Trim()
                : rawUrl;

            // Look for the next snippet text in the subsequent <td> block.
            var snippet = "";
            var tdMarker = html.IndexOf("<td", endA >= 0 ? endA : idx, StringComparison.OrdinalIgnoreCase);
            if (tdMarker >= 0)
            {
                var tdClose = html.IndexOf('>', tdMarker);
                var tdEnd = html.IndexOf("</td>", tdClose >= 0 ? tdClose : tdMarker, StringComparison.OrdinalIgnoreCase);
                if (tdClose >= 0 && tdEnd > tdClose)
                    snippet = StripHtmlTags(html[(tdClose + 1)..tdEnd]).Trim();
            }

            // Decode the redirect URL if needed.
            var url = rawUrl;
            if (rawUrl.Contains("uddg="))
            {
                var uddgIdx = rawUrl.IndexOf("uddg=", StringComparison.Ordinal) + 5;
                var ampIdx = rawUrl.IndexOf('&', uddgIdx);
                var encodedUrl = ampIdx > 0 ? rawUrl[uddgIdx..ampIdx] : rawUrl[uddgIdx..];
                url = WebUtility.UrlDecode(encodedUrl);
            }

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(title, url, snippet));

            idx = endQuote + 1;
        }

        return results;
    }

    private static string StripHtmlTags(string html)
    {
        var sb = new StringBuilder(html.Length);
        var inTag = false;

        foreach (var c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) sb.Append(c);
        }

        // Collapse whitespace.
        var text = sb.ToString();
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
        return WebUtility.HtmlDecode(text.Trim());
    }

    public record NoteEntry(string Topic, string Content, DateTime Timestamp);
    private record SearchResult(string Title, string Url, string Snippet);
}

