using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the chat client ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Register tools ---
var tools = new ResearchTools();

// --- Create the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using the SearchWeb tool.
        2. Read the most promising pages with FetchPage.
        3. Save key findings as notes using SaveNote — organize notes by subtopic.
        4. After gathering enough information (at least 3 sources), retrieve your notes with GetNotes.
        5. Produce a final well-structured summary with key findings and source URLs.
        Be thorough but concise. Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches a topic by searching the web, reading pages, taking notes, and summarizing findings.",
    tools: [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.FetchPage),
        AIFunctionFactory.Create(tools.SaveNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ]);

// --- Get the research topic ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// --- Run the agent ---
var session = await agent.CreateSessionAsync("research-session");

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

// --- Display saved notes ---
if (tools.Notes.Count > 0)
{
    Console.WriteLine($"\n--- {tools.Notes.Count} research note(s) saved during this session ---");
    foreach (var note in tools.Notes)
    {
        Console.WriteLine($"  [{note.Topic}] {note.Content[..Math.Min(note.Content.Length, 80)]}...");
    }
}

