        AIFunctionFactory.Create(tools.FetchPage),
        AIFunctionFactory.Create(tools.SaveNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

// --- Create the agent ---
var agent = new ChatClientAgent(chatClient, chatOptions)
{
